class Translator:
    def __init__(self, language: str = "de") -> None:
        self.language = language if language in TEXTS else "de"

    def __call__(self, key: str) -> str:
        return TEXTS[self.language].get(key, TEXTS["de"].get(key, key))

    def format(self, key: str, **values: object) -> str:
        return self(key).format(**values)


