def localize_widget_tree(widget: object, translator: Translator) -> None:
    """Translate static visible controls after construction without a GUI framework."""
    if translator.language == "de":
        return
    try:
        value = widget.cget("text")
        key = VISIBLE_TEXT_KEYS.get(value)
        if key:
            widget.configure(text=translator(key))
    except Exception:
        pass
    try:
        for child in widget.winfo_children():
            localize_widget_tree(child, translator)
    except Exception:
        pass
